-- PROPOSED ONLY: do not apply to production without reviewed migration approval.
-- Filename generated by Supabase CLI 3.1.0; validate deployed history before applying.
-- Preflight: inspect deployed constraints/history, duplicate customer/subscription IDs, and
-- legacy mappings. Never infer livemode from cus_ IDs. Verify each legacy Customer with Stripe,
-- then call billing_link_customer(user_id, customer_id, verified_livemode).
-- This migration does not enable tax registrations or external accounting exports.
BEGIN;

ALTER TABLE public.subscriptions
  ADD COLUMN IF NOT EXISTS stripe_price_id text,
  ADD COLUMN IF NOT EXISTS stripe_livemode boolean,
  ADD COLUMN IF NOT EXISTS current_period_start timestamptz,
  ADD COLUMN IF NOT EXISTS cancel_at_period_end boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS canceled_at timestamptz,
  ADD COLUMN IF NOT EXISTS trial_end timestamptz,
  ADD COLUMN IF NOT EXISTS billing_synced_at timestamptz,
  ADD COLUMN IF NOT EXISTS last_invoice_provider text,
  ADD COLUMN IF NOT EXISTS last_invoice_number text,
  ADD COLUMN IF NOT EXISTS last_invoice_url text;
-- The tracked baseline uses this default CHECK name. Verify drift before deployment.
ALTER TABLE public.subscriptions DROP CONSTRAINT IF EXISTS subscriptions_status_check;
ALTER TABLE public.subscriptions ADD CONSTRAINT subscriptions_status_check CHECK (
  status IN ('active','trialing','past_due','canceled','incomplete','incomplete_expired','unpaid','paused')
);
-- Fail visibly on legacy duplicates; do not silently pick an owner.
CREATE UNIQUE INDEX IF NOT EXISTS billing_subscription_customer_unique
  ON public.subscriptions(stripe_customer_id) WHERE stripe_customer_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS billing_subscription_id_unique
  ON public.subscriptions(stripe_subscription_id) WHERE stripe_subscription_id IS NOT NULL;

CREATE TABLE public.billing_customers (
  user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  stripe_customer_id text NOT NULL UNIQUE CHECK (stripe_customer_id ~ '^cus_[A-Za-z0-9_]+$'),
  livemode boolean NOT NULL,
  checkout_session_id text,
  lease_token uuid,
  lease_generation bigint NOT NULL DEFAULT 0 CHECK (lease_generation BETWEEN 0 AND 9007199254740991),
  lease_kind text CHECK (lease_kind IN ('checkout','event')),
  lease_expires_at timestamptz,
  lease_event_id text,
  lease_checkout_operation_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (
    (lease_token IS NULL AND lease_kind IS NULL AND lease_expires_at IS NULL
      AND lease_event_id IS NULL AND lease_checkout_operation_id IS NULL)
    OR
    (lease_token IS NOT NULL AND lease_kind IS NOT NULL AND lease_expires_at IS NOT NULL
      AND ((lease_kind='event' AND lease_event_id IS NOT NULL AND lease_checkout_operation_id IS NULL)
        OR (lease_kind='checkout' AND lease_event_id IS NULL AND lease_checkout_operation_id IS NOT NULL)))
  )
);

CREATE TABLE public.billing_checkout_operations (
  operation_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  customer_id text NOT NULL REFERENCES public.billing_customers(stripe_customer_id),
  livemode boolean NOT NULL,
  request_hash text NOT NULL CHECK (request_hash ~ '^[a-f0-9]{64}$'),
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','completed')),
  checkout_session_id text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (status <> 'completed' OR checkout_session_id IS NOT NULL)
);
CREATE UNIQUE INDEX billing_checkout_one_pending
  ON public.billing_checkout_operations(customer_id) WHERE status='pending';

CREATE TABLE public.billing_checkout_requests (
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  request_id uuid NOT NULL,
  request_hash text NOT NULL CHECK (request_hash ~ '^[a-f0-9]{64}$'),
  operation_id uuid NOT NULL REFERENCES public.billing_checkout_operations(operation_id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id,request_id)
);

CREATE TABLE public.billing_webhook_events (
  event_id text PRIMARY KEY CHECK (event_id ~ '^evt_[A-Za-z0-9_]+$'),
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  customer_id text NOT NULL REFERENCES public.billing_customers(stripe_customer_id),
  livemode boolean NOT NULL,
  event_type text NOT NULL CHECK (event_type IN (
    'checkout.session.completed','checkout.session.async_payment_succeeded','checkout.session.async_payment_failed',
    'customer.subscription.created','customer.subscription.updated','customer.subscription.deleted',
    'customer.subscription.paused','customer.subscription.resumed',
    'invoice.payment_succeeded','invoice.payment_failed','invoice.paid'
  )),
  status text NOT NULL CHECK (status IN ('processing','failed','completed')),
  attempts integer NOT NULL DEFAULT 1 CHECK (attempts > 0),
  lease_token uuid,
  generation bigint,
  last_error_code text CHECK (last_error_code IS NULL OR last_error_code ~ '^[A-Z0-9_:-]{1,100}$'),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz
);

CREATE TABLE public.billing_invoice_references (
  invoice_id text PRIMARY KEY CHECK (invoice_id ~ '^in_[A-Za-z0-9_]+$'),
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  customer_id text NOT NULL REFERENCES public.billing_customers(stripe_customer_id),
  livemode boolean NOT NULL,
  subscription_id text,
  invoice_number text,
  hosted_invoice_url text,
  invoice_pdf_url text,
  status text CHECK (status IN ('draft','open','paid','uncollectible','void')),
  currency text NOT NULL CHECK (currency ~ '^[a-z]{3}$'),
  amount_paid bigint NOT NULL CHECK (amount_paid >= 0),
  stripe_created bigint NOT NULL CHECK (stripe_created BETWEEN 0 AND 253402300799),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX billing_invoice_owner_created
  ON public.billing_invoice_references(user_id,stripe_created DESC,invoice_id DESC);

ALTER TABLE public.billing_customers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.billing_customers FORCE ROW LEVEL SECURITY;
ALTER TABLE public.billing_checkout_operations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.billing_checkout_operations FORCE ROW LEVEL SECURITY;
ALTER TABLE public.billing_checkout_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.billing_checkout_requests FORCE ROW LEVEL SECURITY;
ALTER TABLE public.billing_webhook_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.billing_webhook_events FORCE ROW LEVEL SECURITY;
ALTER TABLE public.billing_invoice_references ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.billing_invoice_references FORCE ROW LEVEL SECURITY;
REVOKE ALL ON public.billing_customers, public.billing_checkout_operations,
  public.billing_checkout_requests, public.billing_webhook_events, public.billing_invoice_references
  FROM public, anon, authenticated;
GRANT ALL ON public.billing_customers, public.billing_checkout_operations,
  public.billing_checkout_requests, public.billing_webhook_events, public.billing_invoice_references
  TO service_role;
GRANT SELECT ON public.billing_invoice_references TO authenticated;
CREATE POLICY billing_invoice_owner_read ON public.billing_invoice_references
  FOR SELECT TO authenticated USING ((SELECT auth.uid())=user_id);

-- SECURITY INVOKER plus service-role-only EXECUTE. No definer privilege bypass.
CREATE FUNCTION public.billing_link_customer(p_user_id uuid,p_customer_id text,p_livemode boolean)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public AS $$
DECLARE v_customer public.billing_customers%ROWTYPE; v_existing_customer text;
BEGIN
  INSERT INTO public.billing_customers(user_id,stripe_customer_id,livemode)
    VALUES(p_user_id,p_customer_id,p_livemode) ON CONFLICT(user_id) DO NOTHING;
  SELECT * INTO STRICT v_customer FROM public.billing_customers WHERE user_id=p_user_id FOR UPDATE;
  IF v_customer.stripe_customer_id<>p_customer_id OR v_customer.livemode<>p_livemode THEN
    RAISE EXCEPTION 'BILLING_CUSTOMER_CONFLICT' USING ERRCODE='23505';
  END IF;
  SELECT stripe_customer_id INTO v_existing_customer FROM public.subscriptions WHERE user_id=p_user_id FOR UPDATE;
  IF v_existing_customer IS NOT NULL AND v_existing_customer<>p_customer_id THEN
    RAISE EXCEPTION 'BILLING_LEGACY_CUSTOMER_CONFLICT' USING ERRCODE='23505';
  END IF;
  INSERT INTO public.subscriptions(user_id,stripe_customer_id,stripe_livemode)
    VALUES(p_user_id,p_customer_id,p_livemode)
    ON CONFLICT(user_id) DO UPDATE SET stripe_customer_id=EXCLUDED.stripe_customer_id,
      stripe_livemode=EXCLUDED.stripe_livemode,updated_at=now();
  RETURN jsonb_build_object('linked',true);
END $$;

CREATE FUNCTION public.billing_claim_checkout(
  p_user_id uuid,p_customer_id text,p_livemode boolean,p_request_id uuid,p_request_hash text
) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public AS $$
DECLARE
  v_customer public.billing_customers%ROWTYPE;
  v_operation public.billing_checkout_operations%ROWTYPE;
  v_pending public.billing_checkout_operations%ROWTYPE;
  v_request public.billing_checkout_requests%ROWTYPE;
  v_subscription text;
BEGIN
  IF p_request_hash IS NULL OR p_request_hash !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'INVALID_REQUEST_HASH' USING ERRCODE='22023';
  END IF;
  SELECT * INTO v_customer FROM public.billing_customers WHERE user_id=p_user_id FOR UPDATE;
  IF NOT FOUND OR v_customer.stripe_customer_id<>p_customer_id OR v_customer.livemode<>p_livemode THEN
    RETURN jsonb_build_object('status','unmapped');
  END IF;
  SELECT * INTO v_request FROM public.billing_checkout_requests
    WHERE user_id=p_user_id AND request_id=p_request_id;
  IF FOUND THEN
    IF v_request.request_hash<>p_request_hash THEN
      RETURN jsonb_build_object('status','conflict','code','REQUEST_INPUT_CONFLICT');
    END IF;
    SELECT * INTO STRICT v_operation FROM public.billing_checkout_operations
      WHERE operation_id=v_request.operation_id;
  END IF;
  SELECT * INTO v_pending FROM public.billing_checkout_operations
    WHERE customer_id=p_customer_id AND status='pending';
  IF FOUND THEN
    IF v_pending.request_hash<>p_request_hash THEN
      RETURN jsonb_build_object('status','conflict','code','CHECKOUT_PENDING_INPUT_CONFLICT');
    END IF;
    IF v_operation.operation_id IS NOT NULL AND v_operation.operation_id<>v_pending.operation_id THEN
      RETURN jsonb_build_object('status','conflict','code','CHECKOUT_PENDING_OTHER_OPERATION');
    END IF;
    v_operation := v_pending;
    -- Stripe may prune idempotency records after 24h. Stop blind retry before that boundary.
    IF v_operation.created_at < clock_timestamp()-interval '23 hours' THEN
      RETURN jsonb_build_object('status','blocked','code','CHECKOUT_OPERATION_RECONCILIATION_REQUIRED');
    END IF;
  END IF;
  IF v_customer.lease_token IS NOT NULL AND v_customer.lease_expires_at>clock_timestamp() THEN
    RETURN jsonb_build_object('status','busy');
  END IF;
  IF v_operation.operation_id IS NULL THEN
    INSERT INTO public.billing_checkout_operations(user_id,customer_id,livemode,request_hash)
      VALUES(p_user_id,p_customer_id,p_livemode,p_request_hash) RETURNING * INTO v_operation;
  END IF;
  IF v_operation.user_id<>p_user_id OR v_operation.customer_id<>p_customer_id OR v_operation.livemode<>p_livemode THEN
    RAISE EXCEPTION 'CHECKOUT_OPERATION_OWNER_MISMATCH' USING ERRCODE='23514';
  END IF;
  INSERT INTO public.billing_checkout_requests(user_id,request_id,request_hash,operation_id)
    VALUES(p_user_id,p_request_id,p_request_hash,v_operation.operation_id)
    ON CONFLICT(user_id,request_id) DO NOTHING;
  UPDATE public.billing_customers SET
    lease_token=gen_random_uuid(),lease_generation=lease_generation+1,lease_kind='checkout',
    lease_expires_at=clock_timestamp()+interval '180 seconds',lease_event_id=NULL,
    lease_checkout_operation_id=v_operation.operation_id,updated_at=now()
    WHERE user_id=p_user_id RETURNING * INTO v_customer;
  SELECT stripe_subscription_id INTO v_subscription FROM public.subscriptions WHERE user_id=p_user_id;
  RETURN jsonb_build_object('status','claimed','userId',p_user_id,'customerId',p_customer_id,
    'livemode',p_livemode,'leaseToken',v_customer.lease_token,'generation',v_customer.lease_generation,
    'checkoutSessionId',COALESCE(v_operation.checkout_session_id,v_customer.checkout_session_id),
    'checkoutOperationId',v_operation.operation_id,'checkoutOperationCompleted',v_operation.status='completed',
    'currentSubscriptionId',v_subscription);
END $$;

CREATE FUNCTION public.billing_finalize_checkout(
  p_user_id uuid,p_customer_id text,p_livemode boolean,p_lease_token uuid,p_generation bigint,
  p_operation_id uuid,p_session_id text
) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public AS $$
DECLARE v_customer public.billing_customers%ROWTYPE; v_operation public.billing_checkout_operations%ROWTYPE;
BEGIN
  SELECT * INTO v_customer FROM public.billing_customers WHERE user_id=p_user_id FOR UPDATE;
  IF NOT FOUND OR v_customer.stripe_customer_id<>p_customer_id OR v_customer.livemode<>p_livemode
    OR v_customer.lease_token IS DISTINCT FROM p_lease_token OR v_customer.lease_generation<>p_generation
    OR v_customer.lease_kind IS DISTINCT FROM 'checkout'
    OR v_customer.lease_checkout_operation_id IS DISTINCT FROM p_operation_id
    OR v_customer.lease_expires_at<=clock_timestamp() THEN
    RETURN jsonb_build_object('applied',false);
  END IF;
  IF p_session_id IS NULL OR p_session_id !~ '^cs_[A-Za-z0-9_]+$' THEN
    RAISE EXCEPTION 'INVALID_CHECKOUT_SESSION' USING ERRCODE='22023';
  END IF;
  SELECT * INTO STRICT v_operation FROM public.billing_checkout_operations WHERE operation_id=p_operation_id FOR UPDATE;
  IF v_operation.user_id<>p_user_id OR v_operation.customer_id<>p_customer_id OR v_operation.livemode<>p_livemode
    OR (v_operation.status='completed' AND v_operation.checkout_session_id<>p_session_id) THEN
    RAISE EXCEPTION 'CHECKOUT_OPERATION_CONFLICT' USING ERRCODE='23514';
  END IF;
  UPDATE public.billing_checkout_operations SET status='completed',checkout_session_id=p_session_id,updated_at=now()
    WHERE operation_id=p_operation_id;
  UPDATE public.billing_customers SET checkout_session_id=p_session_id,lease_token=NULL,lease_kind=NULL,
    lease_expires_at=NULL,lease_event_id=NULL,lease_checkout_operation_id=NULL,updated_at=now() WHERE user_id=p_user_id;
  RETURN jsonb_build_object('applied',true);
END $$;

CREATE FUNCTION public.billing_fail_checkout(
  p_user_id uuid,p_customer_id text,p_livemode boolean,p_lease_token uuid,p_generation bigint,p_operation_id uuid
) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public AS $$
DECLARE v_changed integer;
BEGIN
  UPDATE public.billing_customers SET lease_token=NULL,lease_kind=NULL,lease_expires_at=NULL,
    lease_event_id=NULL,lease_checkout_operation_id=NULL,updated_at=now()
    WHERE user_id=p_user_id AND stripe_customer_id=p_customer_id AND livemode=p_livemode
      AND lease_token=p_lease_token AND lease_generation=p_generation AND lease_kind='checkout'
      AND lease_checkout_operation_id=p_operation_id;
  GET DIAGNOSTICS v_changed=ROW_COUNT;
  -- Do not erase the pending operation or its Stripe idempotency identity.
  RETURN jsonb_build_object('applied',v_changed=1);
END $$;

CREATE FUNCTION public.billing_claim_event(
  p_event_id text,p_event_type text,p_customer_id text,p_livemode boolean
) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public AS $$
DECLARE v_customer public.billing_customers%ROWTYPE; v_event public.billing_webhook_events%ROWTYPE; v_subscription text;
BEGIN
  SELECT * INTO v_customer FROM public.billing_customers WHERE stripe_customer_id=p_customer_id FOR UPDATE;
  IF NOT FOUND OR v_customer.livemode<>p_livemode THEN
    RETURN jsonb_build_object('status','unmapped');
  END IF;
  SELECT * INTO v_event FROM public.billing_webhook_events WHERE event_id=p_event_id FOR UPDATE;
  IF FOUND THEN
    IF v_event.customer_id<>p_customer_id OR v_event.livemode<>p_livemode OR v_event.event_type<>p_event_type THEN
      RAISE EXCEPTION 'WEBHOOK_EVENT_ID_CONFLICT' USING ERRCODE='23514';
    END IF;
    IF v_event.status='completed' THEN RETURN jsonb_build_object('status','completed'); END IF;
  END IF;
  IF v_customer.lease_token IS NOT NULL AND v_customer.lease_expires_at>clock_timestamp() THEN
    RETURN jsonb_build_object('status','busy');
  END IF;
  UPDATE public.billing_customers SET lease_token=gen_random_uuid(),lease_generation=lease_generation+1,
    lease_kind='event',lease_expires_at=clock_timestamp()+interval '180 seconds',
    lease_event_id=p_event_id,lease_checkout_operation_id=NULL,updated_at=now()
    WHERE user_id=v_customer.user_id RETURNING * INTO v_customer;
  INSERT INTO public.billing_webhook_events(event_id,user_id,customer_id,livemode,event_type,status,lease_token,generation)
    VALUES(p_event_id,v_customer.user_id,p_customer_id,p_livemode,p_event_type,'processing',
      v_customer.lease_token,v_customer.lease_generation)
    ON CONFLICT(event_id) DO UPDATE SET status='processing',attempts=billing_webhook_events.attempts+1,
      lease_token=EXCLUDED.lease_token,generation=EXCLUDED.generation,last_error_code=NULL,updated_at=now();
  SELECT stripe_subscription_id INTO v_subscription FROM public.subscriptions WHERE user_id=v_customer.user_id;
  RETURN jsonb_build_object('status','claimed','userId',v_customer.user_id,'customerId',p_customer_id,
    'livemode',p_livemode,'leaseToken',v_customer.lease_token,'generation',v_customer.lease_generation,
    'checkoutSessionId',v_customer.checkout_session_id,'checkoutOperationId',NULL,'currentSubscriptionId',v_subscription);
END $$;

CREATE FUNCTION public.billing_finalize_event(
  p_user_id uuid,p_customer_id text,p_livemode boolean,p_lease_token uuid,p_generation bigint,
  p_event_id text,p_projection jsonb,p_invoice_reference jsonb,p_checkout_reference jsonb DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public AS $$
DECLARE
  v_customer public.billing_customers%ROWTYPE;
  v_event public.billing_webhook_events%ROWTYPE;
  v_invoice public.billing_invoice_references%ROWTYPE;
  v_operation public.billing_checkout_operations%ROWTYPE;
  v_existing_customer text;
BEGIN
  SELECT * INTO v_customer FROM public.billing_customers WHERE user_id=p_user_id FOR UPDATE;
  IF NOT FOUND OR v_customer.stripe_customer_id<>p_customer_id OR v_customer.livemode<>p_livemode
    OR v_customer.lease_token IS DISTINCT FROM p_lease_token OR v_customer.lease_generation<>p_generation
    OR v_customer.lease_kind IS DISTINCT FROM 'event' OR v_customer.lease_event_id IS DISTINCT FROM p_event_id
    OR v_customer.lease_expires_at<=clock_timestamp() THEN
    RETURN jsonb_build_object('applied',false);
  END IF;
  SELECT * INTO v_event FROM public.billing_webhook_events WHERE event_id=p_event_id FOR UPDATE;
  IF NOT FOUND OR v_event.status<>'processing' OR v_event.lease_token IS DISTINCT FROM p_lease_token
    OR v_event.generation<>p_generation OR v_event.user_id<>p_user_id THEN
    RETURN jsonb_build_object('applied',false);
  END IF;
  IF p_projection IS NULL OR jsonb_typeof(p_projection)<>'object'
    OR NOT (p_projection ?& ARRAY['subscriptionId','priceId','plan','status','currentPeriodStart',
      'currentPeriodEnd','cancelAtPeriodEnd','canceledAt','trialEnd']) THEN
    RAISE EXCEPTION 'INVALID_SUBSCRIPTION_PROJECTION' USING ERRCODE='22023';
  END IF;
  SELECT stripe_customer_id INTO v_existing_customer FROM public.subscriptions WHERE user_id=p_user_id FOR UPDATE;
  IF v_existing_customer IS NOT NULL AND v_existing_customer<>p_customer_id THEN
    RAISE EXCEPTION 'SUBSCRIPTION_OWNER_CONFLICT' USING ERRCODE='23514';
  END IF;
  INSERT INTO public.subscriptions(user_id,stripe_customer_id,stripe_subscription_id,stripe_price_id,stripe_livemode,
    plan,status,current_period_start,current_period_end,cancel_at_period_end,canceled_at,trial_end,billing_synced_at,updated_at)
  VALUES(p_user_id,p_customer_id,p_projection->>'subscriptionId',p_projection->>'priceId',p_livemode,
    p_projection->>'plan',p_projection->>'status',(p_projection->>'currentPeriodStart')::timestamptz,
    (p_projection->>'currentPeriodEnd')::timestamptz,(p_projection->>'cancelAtPeriodEnd')::boolean,
    (p_projection->>'canceledAt')::timestamptz,(p_projection->>'trialEnd')::timestamptz,now(),now())
  ON CONFLICT(user_id) DO UPDATE SET stripe_customer_id=EXCLUDED.stripe_customer_id,
    stripe_subscription_id=EXCLUDED.stripe_subscription_id,stripe_price_id=EXCLUDED.stripe_price_id,
    stripe_livemode=EXCLUDED.stripe_livemode,plan=EXCLUDED.plan,status=EXCLUDED.status,
    current_period_start=EXCLUDED.current_period_start,current_period_end=EXCLUDED.current_period_end,
    cancel_at_period_end=EXCLUDED.cancel_at_period_end,canceled_at=EXCLUDED.canceled_at,
    trial_end=EXCLUDED.trial_end,billing_synced_at=EXCLUDED.billing_synced_at,updated_at=now();

  IF p_invoice_reference IS NOT NULL AND p_invoice_reference<>'null'::jsonb THEN
    SELECT * INTO v_invoice FROM public.billing_invoice_references WHERE invoice_id=p_invoice_reference->>'id' FOR UPDATE;
    IF FOUND AND (v_invoice.user_id<>p_user_id OR v_invoice.customer_id<>p_customer_id OR v_invoice.livemode<>p_livemode) THEN
      RAISE EXCEPTION 'INVOICE_OWNER_CONFLICT' USING ERRCODE='23514';
    END IF;
    INSERT INTO public.billing_invoice_references(invoice_id,user_id,customer_id,livemode,subscription_id,invoice_number,
      hosted_invoice_url,invoice_pdf_url,status,currency,amount_paid,stripe_created)
    VALUES(p_invoice_reference->>'id',p_user_id,p_customer_id,p_livemode,p_invoice_reference->>'subscriptionId',
      p_invoice_reference->>'number',p_invoice_reference->>'hostedInvoiceUrl',p_invoice_reference->>'invoicePdfUrl',
      p_invoice_reference->>'status',p_invoice_reference->>'currency',(p_invoice_reference->>'amountPaid')::bigint,
      (p_invoice_reference->>'created')::bigint)
    ON CONFLICT(invoice_id) DO UPDATE SET subscription_id=EXCLUDED.subscription_id,invoice_number=EXCLUDED.invoice_number,
      hosted_invoice_url=EXCLUDED.hosted_invoice_url,invoice_pdf_url=EXCLUDED.invoice_pdf_url,status=EXCLUDED.status,
      currency=EXCLUDED.currency,amount_paid=EXCLUDED.amount_paid,stripe_created=EXCLUDED.stripe_created,updated_at=now();
    -- This sorts real Stripe invoice creation times only for display, never webhook ordering.
    SELECT * INTO v_invoice FROM public.billing_invoice_references
      WHERE user_id=p_user_id AND livemode=p_livemode ORDER BY stripe_created DESC,invoice_id DESC LIMIT 1;
    UPDATE public.subscriptions SET last_invoice_provider='stripe',last_invoice_number=v_invoice.invoice_number,
      last_invoice_url=v_invoice.hosted_invoice_url WHERE user_id=p_user_id;
  END IF;

  IF p_checkout_reference IS NOT NULL AND p_checkout_reference<>'null'::jsonb THEN
    SELECT * INTO v_operation FROM public.billing_checkout_operations
      WHERE operation_id=(p_checkout_reference->>'operationId')::uuid FOR UPDATE;
    IF NOT FOUND OR v_operation.user_id<>p_user_id OR v_operation.customer_id<>p_customer_id OR v_operation.livemode<>p_livemode
      OR v_operation.request_hash IS DISTINCT FROM p_checkout_reference->>'requestHash'
      OR (v_operation.status='completed' AND v_operation.checkout_session_id<>p_checkout_reference->>'sessionId') THEN
      RAISE EXCEPTION 'CHECKOUT_EVENT_OPERATION_CONFLICT' USING ERRCODE='23514';
    END IF;
    UPDATE public.billing_checkout_operations SET status='completed',
      checkout_session_id=p_checkout_reference->>'sessionId',updated_at=now() WHERE operation_id=v_operation.operation_id;
    -- A delayed event for an already completed older operation must not replace a newer checkout pointer.
    IF v_operation.status='pending' OR v_customer.checkout_session_id IS NULL THEN
      UPDATE public.billing_customers SET checkout_session_id=p_checkout_reference->>'sessionId' WHERE user_id=p_user_id;
    END IF;
  END IF;
  UPDATE public.billing_webhook_events SET status='completed',completed_at=now(),updated_at=now(),
    last_error_code=NULL WHERE event_id=p_event_id;
  UPDATE public.billing_customers SET lease_token=NULL,lease_kind=NULL,lease_expires_at=NULL,
    lease_event_id=NULL,lease_checkout_operation_id=NULL,updated_at=now() WHERE user_id=p_user_id;
  RETURN jsonb_build_object('applied',true);
END $$;

CREATE FUNCTION public.billing_fail_event(
  p_user_id uuid,p_customer_id text,p_livemode boolean,p_lease_token uuid,p_generation bigint,p_event_id text,p_error_code text
) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public AS $$
DECLARE v_customer public.billing_customers%ROWTYPE;
BEGIN
  SELECT * INTO v_customer FROM public.billing_customers WHERE user_id=p_user_id FOR UPDATE;
  IF NOT FOUND OR v_customer.stripe_customer_id<>p_customer_id OR v_customer.livemode<>p_livemode
    OR v_customer.lease_token IS DISTINCT FROM p_lease_token OR v_customer.lease_generation<>p_generation
    OR v_customer.lease_kind IS DISTINCT FROM 'event' OR v_customer.lease_event_id IS DISTINCT FROM p_event_id THEN
    RETURN jsonb_build_object('applied',false);
  END IF;
  UPDATE public.billing_webhook_events SET status='failed',last_error_code=p_error_code,updated_at=now()
    WHERE event_id=p_event_id AND lease_token=p_lease_token AND generation=p_generation AND status='processing';
  UPDATE public.billing_customers SET lease_token=NULL,lease_kind=NULL,lease_expires_at=NULL,
    lease_event_id=NULL,lease_checkout_operation_id=NULL,updated_at=now() WHERE user_id=p_user_id;
  RETURN jsonb_build_object('applied',true);
END $$;

REVOKE ALL ON FUNCTION public.billing_link_customer(uuid,text,boolean) FROM public,anon,authenticated;
REVOKE ALL ON FUNCTION public.billing_claim_checkout(uuid,text,boolean,uuid,text) FROM public,anon,authenticated;
REVOKE ALL ON FUNCTION public.billing_finalize_checkout(uuid,text,boolean,uuid,bigint,uuid,text) FROM public,anon,authenticated;
REVOKE ALL ON FUNCTION public.billing_fail_checkout(uuid,text,boolean,uuid,bigint,uuid) FROM public,anon,authenticated;
REVOKE ALL ON FUNCTION public.billing_claim_event(text,text,text,boolean) FROM public,anon,authenticated;
REVOKE ALL ON FUNCTION public.billing_finalize_event(uuid,text,boolean,uuid,bigint,text,jsonb,jsonb,jsonb) FROM public,anon,authenticated;
REVOKE ALL ON FUNCTION public.billing_fail_event(uuid,text,boolean,uuid,bigint,text,text) FROM public,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.billing_link_customer(uuid,text,boolean) TO service_role;
GRANT EXECUTE ON FUNCTION public.billing_claim_checkout(uuid,text,boolean,uuid,text) TO service_role;
GRANT EXECUTE ON FUNCTION public.billing_finalize_checkout(uuid,text,boolean,uuid,bigint,uuid,text) TO service_role;
GRANT EXECUTE ON FUNCTION public.billing_fail_checkout(uuid,text,boolean,uuid,bigint,uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.billing_claim_event(text,text,text,boolean) TO service_role;
GRANT EXECUTE ON FUNCTION public.billing_finalize_event(uuid,text,boolean,uuid,bigint,text,jsonb,jsonb,jsonb) TO service_role;
GRANT EXECUTE ON FUNCTION public.billing_fail_event(uuid,text,boolean,uuid,bigint,text,text) TO service_role;

-- Preserve the existing helper's signature/security/search_path, if the Drizzle history installed it.
DO $migration$
BEGIN
  IF to_regprocedure('public.has_agency_plan(uuid)') IS NOT NULL THEN
    EXECUTE $definition$
      CREATE OR REPLACE FUNCTION public.has_agency_plan(_user_id uuid)
      RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $body$
        SELECT EXISTS (SELECT 1 FROM public.subscriptions
          WHERE user_id=_user_id AND plan='agency' AND status IN ('active','trialing')
            AND current_period_end>now())
      $body$
    $definition$;
  END IF;
END
$migration$;
COMMIT;
